// 界面文案数据：14 种语言 × 325 个键。
//
// **本文件由 tools/i18n/gen-locdata.ps1 生成，不要手改。** 改文案请改 `tools/i18n/source.json`
// 或 `tools/i18n/locales/<lang>.json` 后重新生成——手改会在下次生成时被覆盖，
// 而且很容易只改到一种语言，留下「这里怎么还是英文」的下一个坑。
//
// 为什么是编译进代码的字面量、而不是运行时读嵌入资源：
//   读文件多一条**运行时**失败路径（资源名对不上 / 流读不出 / JSON 坏了），
//   而它的失败方式正好是最糟的——表为空，玩家看到 record.autosave 这种
//   原始键名，日志里还未必有线索。编译进代码就不可能在运行时缺失。
//
// 语言代码与 `LocalizationManager.langlist` 完全一致（同一份游戏枚举映射）。
