                    ["effects.trackcolor.tip"] = "Remove os eventos de cor dos trilhos para que mantenham uma única cor.",
                    ["effects.resettrackopacity.tip"] = "Define a opacidade dos eventos de movimento de trilho restantes de volta para 100%.",
                    ["effects.resettrackanim.tip"] = "Redefine as animações de aparecimento/desaparecimento dos trilhos para um fade, para que os trilhos não sumam depois que as animações forem removidas.",
                    ["effects.resettrackcolor.tip"] = "Redefine o estilo e a cor do trilho para o trilho padrão laranja.",
                    ["effects.toggleall.tip"] = "Se algum interruptor deste grupo estiver ativo, um clique desativa todos; se todos estiverem desativados, um clique ativa todos. Inclui apenas os interruptores que removem um tipo de evento; os de redefinição e as opções associadas ficam de fora.",
                    ["effects.planetorbit.tip"] = "Remove os eventos de órbita do planeta.",
                    ["effects.planetscale.tip"] = "Remove os eventos de escala do planeta.",
                    ["effects.planetradius.tip"] = "Remove os eventos de raio do planeta.",
                    ["effects.hideicons.tip"] = "Remove os eventos de ocultar ícones.",
                    ["effects.hitsounds.tip"] = "Remove os sons de acerto e os eventos de som personalizado. A música fica em silêncio.",
                    ["effects.holdsounds.tip"] = "Remove os eventos de som de sustentação.",
                    ["effects.checkpoints.tip"] = "Remove os checkpoints, então uma falha no meio da fase te manda de volta ao início.",
                    ["effects.inputevents.tip"] = "Remove os eventos de entrada, como reprodução automática e limites de teclas.",
                    ["effects.framerate.tip"] = "Remove os eventos de mudança de taxa de quadros para que a fase inteira rode a uma só taxa.",
                    ["effects.repeatevents.tip"] = "Remove os eventos de repetição. As seções que o mapa reutiliza por meio deles são expandidas uma vez.",
                    ["record.recording.tip"] = "Chave mestra. Quando desativada, entrar em uma fase não registra nada.",
                    ["record.autosave.tip"] = "Salva esta tentativa como arquivo de replay ao concluir a fase.",
                    ["record.completesave.tip"] = "Salvar apenas conclusões completas. Desative para também manter tentativas abandonadas no meio.",
                    ["record.dontsavewhenauto.tip"] = "Ignora as fases que o jogo reproduziu sozinho, para que a reprodução automática não encha sua lista de replays.",
                    ["record.dontsavewhenmiss.tip"] = "Ignora tentativas que contenham um erro. Desative para manter uma tentativa falha.",
                    ["record.latesave.tip"] = "Salvar ao sair da fase em vez de na tela de resultados.",
                    ["record.failsave.tip"] = "Salvar também ao morrer. Por padrão, um arquivo só é gravado ao concluir ou no salvamento manual.",
                    ["record.backup.tip"] = "Mantém uma cópia extra ao salvar, para que um arquivo existente com o mesmo nome não seja simplesmente sobrescrito.",
                    ["record.manualsave.tip"] = "Permite usar F9 para salvar a tentativa atual manualmente, inclusive no meio de um treino.",
                    ["record.cancelsave.tip"] = "Descarta com uma tecla a tentativa pendente de salvar. Se desativar isto, a tecla abaixo não faz nada.",
                    ["record.asyncinput.tip"] = "Lê as teclas da entrada assíncrona do jogo para timestamps mais precisos. A opção de entrada assíncrona do jogo precisa estar ativada primeiro, ou isto não fará nada.",
                    ["record.keybd.record.tip"] = "Grava o som das teclas como uma faixa separada para que a reprodução tenha sons de teclado.",
                    ["record.keybd.volume.tip"] = "Volume do som de teclado durante a reprodução. 0 = mudo.",
                    ["record.keybd.offset.tip"] = "Calibra o som de teclado como um todo: negativo se estiver adiantado, positivo se atrasado, em milissegundos.",
                    ["record.savekey.tip"] = "Atalho para salvar esta tentativa, F9 por padrão. Clique nele e pressione qualquer tecla para reatribuir.",
                    ["record.cancelsavekey.tip"] = "Atalho que descarta o salvamento pendente desta tentativa.",
                    ["render.on.tip"] = "Chave mestra da renderização de vídeo. Quando desativada, nenhuma nova renderização pode ser iniciada.",
                    ["render.width.tip"] = "Largura de saída. Só é usada pela câmera limpa; a tela do jogo segue o tamanho da janela.",
                    ["render.height.tip"] = "Altura de saída. Só é usada pela câmera limpa.",
                    ["render.fps.tip"] = "Taxa de quadros de saída. Mais alta significa mais fluido, e o tempo de renderização cresce proporcionalmente.",
                    ["render.tail.tip"] = "Segundos extras gravados após o fim da fase, para manter a animação de encerramento.",
                    ["render.surface.tip"] = "Fonte do quadro. A câmera limpa não tem UI e aceita qualquer resolução; a tela do jogo inclui a UI e segue a janela.",
                    ["render.cursor.tip"] = "Desenha o cursor do rato no vídeo. Replays gravados recentemente também guardam a trajetória do cursor, reproduzida ao longo da linha de tempo da música — sincronizada com a imagem e independente da velocidade de renderização. Replays antigos não têm trajetória e usam o cursor em vivo do momento da renderização (o ritmo segue a velocidade de renderização). Um cursor oculto não é desenhado.",
                    ["render.codec.tip"] = "Escolha de codificador. \\\"Mais rápido\\\" prefere codificação por GPU e recorre à CPU quando a sondagem falha; a linha abaixo mostra qual está realmente em uso.",
                    ["render.quality.tip"] = "Qualidade de codificação. Mais alta gera arquivos maiores e renderizações um pouco mais longas.",
                    ["render.format.tip"] = "Contêiner do arquivo de saída. mp4 é o mais compatível; webm ocupa menos mas exige recodificação.",
                    ["render.outdir.tip"] = "Onde os vídeos finalizados vão. Vazio = RenderVideos na pasta do mod.",
                    ["render.clock.experimental.tip"] = "Substitui a fonte de tempo do jogo por um relógio virtual movido pelo índice de quadro para que a taxa de quadros de saída fique constante independentemente da carga da máquina. Altera a própria fonte de tempo do jogo, então seu alcance é amplo; desative isto primeiro se a renderização falhar ou o áudio dessincronizar.",
                    ["convert.target.tip"] = "Converte os vídeos existentes na pasta de saída para este formato, independentemente do formato de renderização acima.",
                    ["render.start.tip"] = "Inicia uma renderização com as configurações atuais. Primeiro carregue um replay e entre na fase dele.",
                    ["render.cancel.tip"] = "Aborta a renderização atual. O que já foi gravado é mantido.",
                    ["convert.button.tip"] = "Inicia a conversão em lote dos vídeos na pasta de saída.",
                    ["record.changedir.tip"] = "Altera a pasta de replays. Não é permitido durante a gravação, ou o som de teclado desta tentativa seria perdido.",
                    ["record.keymap"] = "Remapeamento de teclas",
                    ["record.keymap.tip"] = "Mapeia o código de uma tecla para outra. Útil para controles, teclados com macro ou ferramentas de remapeamento cujos códigos diferem das teclas padrão que o jogo espera.",
                    ["record.keymap.on"] = "Ativar remapeamento de teclas",
