                    ["render.clock.experimental"] = "Horloge de rendu déterministe (expérimental)",
                    ["render.clock.hint"] = "Remplace la source de temps lue par le jeu par une horloge virtuelle pilotée par l'indice d'image, rendant déterministes l'avancement des temps, les événements de caméra, les comptes à rebours et la programmation des sons de touche : la fréquence d'images de sortie reste constante quelle que soit la charge de la machine. Désactivé = repli sur le curseur audio : le rendu fonctionne toujours, mais la ligne de temps est pilotée par le curseur audio (gigue de l'ordre de la milliseconde) et les arrière-plans vidéo ne sont plus calés sur la vitesse de rendu. Remarque : cela modifie la source de temps du jeu lui-même, son impact est donc plus large que celui des autres options ; lorsqu'un autre mod de rendu vidéo est activé en même temps, les deux se disputent le même point de patch (le premier chargé gagne) et cette option s'efface automatiquement. Si le rendu échoue ou qu'un décalage audio/vidéo apparaît, désactivez d'abord cette option.",
