                    ["effects.checkpoints.tip"] = "Retire les checkpoints, donc un échec en cours de niveau vous renvoie au début.",
                    ["effects.inputevents.tip"] = "Retire les événements d'entrée, comme la lecture automatique et les limites de touches.",
                    ["effects.framerate.tip"] = "Retire les événements de changement de fréquence d'images pour que tout le niveau tourne à une seule fréquence.",
                    ["effects.repeatevents.tip"] = "Retire les événements de répétition. Les sections que le chart réutilise via eux sont développées une fois.",
                    ["record.recording.tip"] = "Interrupteur principal. Désactivé, entrer dans un niveau n'enregistre rien.",
                    ["record.autosave.tip"] = "Sauvegarde cette partie comme fichier de replay à la fin du niveau.",
                    ["record.completesave.tip"] = "Sauvegarder seulement les niveaux terminés en entier. Désactivez pour conserver aussi les parties abandonnées en cours de route.",
                    ["record.dontsavewhenauto.tip"] = "Ignore les niveaux que le jeu a joués tout seul, pour que la lecture automatique n'inonde pas votre liste de replays.",
                    ["record.dontsavewhenmiss.tip"] = "Ignore les parties contenant une erreur. Désactivez pour conserver une tentative ratée.",
                    ["record.latesave.tip"] = "Sauvegarde en quittant le niveau plutôt qu'à l'écran de résultats.",
                    ["record.failsave.tip"] = "Sauvegarde aussi en cas de mort. Par défaut, un fichier n'est écrit qu'à la réussite ou lors d'une sauvegarde manuelle.",
                    ["record.backup.tip"] = "Garde une copie supplémentaire lors de la sauvegarde, pour qu'un fichier existant du même nom ne soit pas simplement écrasé.",
                    ["record.manualsave.tip"] = "Permet d'utiliser F9 pour sauvegarder manuellement la partie en cours, y compris en plein entraînement.",
                    ["record.cancelsave.tip"] = "Permet d'annuler avec un raccourci la sauvegarde en attente de la partie en cours. Si tu désactives cette option, le raccourci ci-dessous ne fait rien.",
                    ["record.asyncinput.tip"] = "Lit les touches depuis l'entrée asynchrone du jeu pour des horodatages plus précis. L'option d'entrée asynchrone du jeu doit d'abord être activée, sinon cela ne fait rien.",
                    ["record.keybd.record.tip"] = "Enregistre le son des touches comme piste séparée pour que la lecture ait des sons de clavier.",
                    ["record.keybd.volume.tip"] = "Volume du son du clavier pendant la lecture. 0 = coupé.",
                    ["record.keybd.offset.tip"] = "Calibre le son du clavier dans son ensemble : négatif s'il est en avance, positif s'il est en retard, en millisecondes.",
                    ["record.savekey.tip"] = "Raccourci pour sauvegarder cette partie, F9 par défaut. Cliquez dessus puis appuyez sur n'importe quelle touche pour le réassigner.",
                    ["record.cancelsavekey.tip"] = "Raccourci qui abandonne la sauvegarde en attente pour cette partie.",
                    ["render.on.tip"] = "Interrupteur principal du rendu vidéo. Désactivé, aucun nouveau rendu ne peut être lancé.",
                    ["render.width.tip"] = "Largeur de sortie. Utilisée uniquement par la caméra propre ; l'écran de jeu suit la taille de la fenêtre.",
                    ["render.height.tip"] = "Hauteur de sortie. Utilisée uniquement par la caméra propre.",
                    ["render.fps.tip"] = "Fréquence d'images de sortie. Plus haute signifie plus fluide, et le temps de rendu augmente proportionnellement.",
                    ["render.tail.tip"] = "Secondes supplémentaires enregistrées après la fin du niveau, pour conserver l'animation de fin.",
                    ["render.surface.tip"] = "Source de l'image. La caméra propre n'a pas d'UI et accepte n'importe quelle résolution ; l'écran de jeu inclut l'UI et suit la fenêtre.",
                    ["render.cursor.tip"] = "Dessine le curseur de la souris dans la vidéo. Les replays nouvellement enregistrés mémorisent aussi la trajectoire du curseur, rejouée le long de la timeline de la chanson — synchronisée avec l'image et indépendante de la vitesse de rendu. Les anciens replays n'ont pas de trajectoire et retombent sur le curseur live du moment du rendu (son rythme suit la vitesse de rendu). Un curseur masqué n'est pas dessiné.",
                    ["render.codec.tip"] = "Choix de l'encodeur. « Le plus rapide » privilégie l'encodage GPU et retombe sur le CPU si la détection échoue ; la ligne ci-dessous indique lequel est réellement utilisé.",
                    ["render.quality.tip"] = "Qualité d'encodage. Plus haute donne des fichiers plus gros et des rendus un peu plus longs.",
                    ["render.format.tip"] = "Conteneur du fichier de sortie. mp4 est le plus compatible ; webm est plus petit mais nécessite un réencodage.",
                    ["render.outdir.tip"] = "Où vont les vidéos terminées. Vide = RenderVideos dans le dossier du mod.",
                    ["render.clock.experimental.tip"] = "Remplace la source de temps du jeu par une horloge virtuelle pilotée par l'indice d'image afin que la fréquence d'images de sortie reste constante quelle que soit la charge de la machine. Cela modifie la source de temps du jeu lui-même, donc son impact est large ; désactivez-la d'abord si le rendu échoue ou que l'audio se désynchronise.",
                    ["convert.target.tip"] = "Convertit les vidéos existantes du dossier de sortie vers ce format, indépendamment du format de rendu ci-dessus.",
                    ["render.start.tip"] = "Lance un rendu avec les réglages actuels. Chargez d'abord un replay et entrez dans son niveau.",
                    ["render.cancel.tip"] = "Interrompt le rendu en cours. Ce qui a déjà été écrit est conservé.",
                    ["convert.button.tip"] = "Lance la conversion par lots des vidéos du dossier de sortie.",
                    ["record.changedir.tip"] = "Change le dossier des replays. Non autorisé pendant l'enregistrement, sinon le son du clavier de cette partie serait perdu.",
                    ["record.keymap"] = "Remappage des touches",
                    ["record.keymap.tip"] = "Associe le code d'une touche à une autre. Utile pour les manettes, les claviers à macros ou les outils de remappage dont les codes diffèrent des touches standard attendues par le jeu.",
                    ["record.keymap.on"] = "Activer le remappage des touches",
                    ["record.keymap.on.tip"] = "Interrupteur principal. Désactivé, les touches sont enregistrées et rejouées telles quelles et le tableau ci-dessous n'a aucun effet.",
                    ["record.keymap.off"] = "Le remappage est désactivé ; les touches sont utilisées telles quelles.",
                    ["record.keymap.off.tip"] = "Explique l'état actuel : le tableau est ignoré.",
                    ["record.keymap.note"] = "À gauche le code réellement envoyé par la touche, à droite la touche que le jeu doit voir. Cliquez sur une case puis appuyez sur n'importe quelle touche pour l'assigner ; Échap annule.",
                    ["record.keymap.note.tip"] = "Explique comment utiliser ce tableau.",
                    ["record.keymap.empty"] = "Aucune entrée pour l'instant. Utilisez le bouton ci-dessous pour en ajouter une.",
                    ["record.keymap.empty.tip"] = "Explique que le tableau est vide.",
                    ["record.keymap.add"] = "Ajouter une entrée",
