                    ["render.clock.hint"] = "Ersetzt die Zeitquelle, die das Spiel liest, durch eine frameindexgesteuerte virtuelle Uhr und macht damit Beat-Fortschritt, Kameraereignisse, Countdowns und die Tastenklang-Planung deterministisch — die Ausgabebildrate bleibt unabhängig von der Maschinenlast konstant. Aus = Rückfall auf den Audio-Cursor: Das Rendern funktioniert weiterhin, aber die Zeitachse wird vom Audio-Cursor gesteuert (Jitter im Millisekundenbereich) und Video-Hintergründe werden nicht mehr auf die Renderrate abgestimmt. Hinweis: Dies verändert die Zeitquelle des Spiels selbst, daher ist die Reichweite größer als bei anderen Optionen; wenn gleichzeitig ein anderes Video-Render-Mod aktiviert ist, konkurrieren beide um denselben Patch-Punkt (wer zuerst lädt, gewinnt) und diese Option weicht automatisch zurück. Wenn das Rendern fehlschlägt oder Audio/Video auseinanderläuft, schalte dies zuerst aus.",
