                    ["effects.gameplay.note"] = "Diese Gruppe verändert das Gameplay selbst. Ohne Checkpoints oder Eingabeereignisse ist das Chart nicht mehr dasselbe wie das Original. Aktiviere sie nur, wenn du dir nur die Spuren ansehen willst.",
                    ["effects.on.tip"] = "Hauptschalter. Wenn aus, entspricht das geladene Chart exakt den Originaldaten; kein einziges Ereignis wird entfernt.",
                    ["effects.enablesave.tip"] = "Erlaubt das Zurückschreiben des aktuellen Charts auf die Festplatte, während die Effektentfernung aktiv ist. Standardmäßig aus: Dies überschreibt die Originaldatei und kann nicht rückgängig gemacht werden.",
                    ["effects.filters.tip"] = "Entfernt Vollbildfilter wie Blitz, Bildschirmwackeln, Spiegelkabinett, Bloom und Bildschirmkachel.",
                    ["effects.advfilters.tip"] = "Entfernt Ereignisse für erweiterte Filter. Getrennt von den einfachen Filtern oben, damit du nur eine Art behalten kannst.",
                    ["effects.particles.tip"] = "Entfernt Ereignisse, die Partikel hinzufügen, ausstoßen oder konfigurieren.",
                    ["effects.backgrounds.tip"] = "Entfernt benutzerdefinierte Hintergründe und leert das Hintergrundvideo, sodass nur eine einfarbige Fläche bleibt.",
                    ["effects.cameras.tip"] = "Entfernt Kamerabewegungsereignisse, damit die Kamera stehen bleibt.",
                    ["effects.setcamerazoom.tip"] = "Fixiert die Kamera auf einen festen Zoom, sobald Kamerabewegungen entfernt wurden. Der Zoom unten bewirkt nichts, solange dies nicht an ist.",
                    ["effects.camerazoom.tip"] = "Zoomstufe, auf die die Kamera fixiert wird. Gilt nur, wenn „Kamerazoom festlegen“ oben an ist.",
                    ["effects.decorations.tip"] = "Entfernt Dekorationen, Text und benutzerdefinierte Objekte aus dem Chart.",
                    ["effects.removealldecor.tip"] = "Leert alle Dekorationen. Wenn aus, bleiben Dekorationen erhalten, auf die bedingte Ereignisse verweisen.",
                    ["effects.trackanim.tip"] = "Entfernt Erscheinen/Verschwinden-Animationen der Spuren, damit Spuren sofort erscheinen.",
                    ["effects.trackpos.tip"] = "Entfernt Positionsereignisse der Spuren.",
                    ["effects.trackmove.tip"] = "Entfernt Spurbewegungsereignisse, die häufigste Art von Spurbewegung.",
                    ["effects.trackcolor.tip"] = "Entfernt Spurfarbenereignisse, damit Spuren eine einzige Farbe behalten.",
                    ["effects.resettrackopacity.tip"] = "Setzt die Deckkraft verbleibender Spurbewegungsereignisse wieder auf 100 %.",
                    ["effects.resettrackanim.tip"] = "Setzt die Erscheinen/Verschwinden-Animationen der Spuren auf ein Ein-/Ausblenden zurück, damit Spuren nach dem Entfernen ihrer Animationen nicht verschwinden.",
                    ["effects.resettrackcolor.tip"] = "Setzt Spurstil und -farbe auf die standardmäßige orange Standardspur zurück.",
                    ["effects.toggleall.tip"] = "Ist ein Schalter dieser Gruppe an, schaltet ein Klick alle aus; sind alle aus, schaltet ein Klick alle ein. Erfasst sind nur die Schalter, die eine Ereignisart entfernen; Zurücksetzen und zugehörige Optionen nicht.",
                    ["effects.planetorbit.tip"] = "Entfernt Planetenorbit-Ereignisse.",
                    ["effects.planetscale.tip"] = "Entfernt Planetengrößen-Ereignisse.",
                    ["effects.planetradius.tip"] = "Entfernt Planetenradius-Ereignisse.",
                    ["effects.hideicons.tip"] = "Entfernt Symbole-ausblenden-Ereignisse.",
                    ["effects.hitsounds.tip"] = "Entfernt Treffertöne und benutzerdefinierte Klangereignisse. Der Song wird still.",
                    ["effects.holdsounds.tip"] = "Entfernt Haltetöne-Ereignisse.",
                    ["effects.checkpoints.tip"] = "Entfernt Checkpoints, sodass ein Fehlschlag mitten im Level dich zum Anfang zurückschickt.",
                    ["effects.inputevents.tip"] = "Entfernt Eingabeereignisse wie Autoplay und Tastenbegrenzungen.",
                    ["effects.framerate.tip"] = "Entfernt Bildratenänderungsereignisse, damit das ganze Level mit einer Rate läuft.",
                    ["effects.repeatevents.tip"] = "Entfernt Wiederholungsereignisse. Abschnitte, die das Chart dadurch wiederverwendet, werden einmal expandiert.",
                    ["record.recording.tip"] = "Hauptschalter. Wenn aus, wird beim Betreten eines Levels nichts aufgezeichnet.",
                    ["record.autosave.tip"] = "Speichert diesen Durchlauf beim Abschluss des Levels als Replay-Datei.",
                    ["record.completesave.tip"] = "Nur vollständige Durchläufe speichern. Schalte es aus, um auch mittendrin abgebrochene Durchläufe zu behalten.",
                    ["record.dontsavewhenauto.tip"] = "Überspringt Level, die das Spiel selbst abgespielt hat, damit Autoplay deine Replay-Liste nicht flutet.",
                    ["record.dontsavewhenmiss.tip"] = "Überspringt Durchläufe mit einem Fehler. Schalte es aus, um einen fehlgeschlagenen Versuch zu behalten.",
                    ["record.latesave.tip"] = "Speichert beim Verlassen des Levels statt am Ergebnisbildschirm.",
                    ["record.failsave.tip"] = "Speichert auch beim Tod. Standardmäßig wird eine Datei nur beim Abschluss oder bei manuellem Speichern geschrieben.",
                    ["record.backup.tip"] = "Behält beim Speichern eine zusätzliche Kopie, damit eine vorhandene gleichnamige Datei nicht einfach überschrieben wird.",
                    ["record.manualsave.tip"] = "Ermöglicht F9 zum manuellen Speichern des aktuellen Durchlaufs, auch mitten im Üben.",
                    ["record.cancelsave.tip"] = "Verwirft mit einer Taste das ausstehende Speichern des aktuellen Durchlaufs. Ist die Option aus, tut die Taste unten nichts.",
                    ["record.asyncinput.tip"] = "Liest Tasten aus der asynchronen Eingabe des Spiels für genauere Zeitstempel. Die Option für asynchrone Eingabe im Spiel muss zuerst aktiviert sein, sonst bewirkt dies stillschweigend nichts.",
                    ["record.keybd.record.tip"] = "Zeichnet den Tastenklang als separate Spur auf, damit die Wiedergabe Tastenklänge hat.",
                    ["record.keybd.volume.tip"] = "Lautstärke des Tastaturklangs während der Wiedergabe. 0 = stumm.",
                    ["record.keybd.offset.tip"] = "Kalibriert den Tastaturklang als Ganzes: negativ, wenn er zu früh kommt, positiv, wenn er zu spät kommt, in Millisekunden.",
                    ["record.savekey.tip"] = "Tastenkürzel zum Speichern dieses Durchlaufs, standardmäßig F9. Klicke darauf und drücke eine beliebige Taste, um es neu zu belegen.",
                    ["record.cancelsavekey.tip"] = "Tastenkürzel, das die ausstehende Speicherung dieses Durchlaufs verwirft.",
                    ["render.on.tip"] = "Hauptschalter für das Videorendern. Wenn aus, kann kein neuer Render gestartet werden.",
                    ["render.width.tip"] = "Ausgabebreite. Wird nur von der sauberen Kamera verwendet; der Spielbildschirm folgt der Fenstergröße.",
                    ["render.height.tip"] = "Ausgabehöhe. Wird nur von der sauberen Kamera verwendet.",
                    ["render.fps.tip"] = "Ausgabebildrate. Höher bedeutet flüssiger, und die Renderzeit wächst proportional.",
                    ["render.tail.tip"] = "Zusätzliche Sekunden, die nach dem Levelende aufgezeichnet werden, um die Outro-Animation zu behalten.",
                    ["render.surface.tip"] = "Bildquelle. Die saubere Kamera hat keine UI und beliebige Auflösung; der Spielbildschirm enthält die UI und folgt dem Fenster.",
                    ["render.cursor.tip"] = "Zeichnet den Mauszeiger ins Video. Neu aufgenommene Replays speichern auch die Zeigerbahn, die beim Rendern entlang der Song-Timeline wiedergegeben wird — synchron zum Bild und unabhängig von der Rendergeschwindigkeit. Ältere Replays haben keine Bahn und greifen auf den Live-Zeiger zur Renderzeit zurück (sein Tempo folgt der Rendergeschwindigkeit). Ein ausgeblendeter Zeiger wird nicht gezeichnet.",
                    ["render.codec.tip"] = "Encoder-Auswahl. „Schnellste“ bevorzugt GPU-Encoding und fällt bei fehlgeschlagener Prüfung auf CPU zurück; die Zeile darunter zeigt, welcher tatsächlich verwendet wird.",
                    ["render.quality.tip"] = "Kodierqualität. Höher ergibt größere Dateien und etwas längere Renderzeiten.",
                    ["render.format.tip"] = "Container für die Ausgabedatei. mp4 ist am kompatibelsten; webm ist kleiner, erfordert aber eine Neukodierung.",
                    ["render.outdir.tip"] = "Wohin fertige Videos gehen. Leer = RenderVideos im Mod-Ordner.",
                    ["render.clock.experimental.tip"] = "Ersetzt die Zeitquelle des Spiels durch eine frameindexgesteuerte virtuelle Uhr, damit die Ausgabebildrate unabhängig von der Maschinenlast konstant bleibt. Dies verändert die Zeitquelle des Spiels selbst, daher ist die Reichweite groß; schalte es zuerst aus, wenn das Rendern fehlschlägt oder das Audio driftet.",
                    ["convert.target.tip"] = "Konvertiert vorhandene Videos im Ausgabeordner in dieses Format, unabhängig vom Renderformat oben.",
                    ["render.start.tip"] = "Startet einen Render mit den aktuellen Einstellungen. Lade zuerst ein Replay und betrete dessen Level.",
                    ["render.cancel.tip"] = "Bricht den aktuellen Render ab. Was bereits geschrieben wurde, bleibt erhalten.",
                    ["convert.button.tip"] = "Startet die Stapelkonvertierung der Videos im Ausgabeordner.",
                    ["record.changedir.tip"] = "Ändert den Replay-Ordner. Während der Aufnahme nicht erlaubt, sonst ginge der Tastaturklang dieses Durchlaufs verloren.",
                    ["record.keymap"] = "Tastenbelegung",
                    ["record.keymap.tip"] = "Ordnet den Code einer Taste einer anderen zu. Nützlich für Controller, Makro-Tastaturen oder Umbelegungstools, deren Codes von den vom Spiel erwarteten Standardtasten abweichen.",
                    ["record.keymap.on"] = "Tastenbelegung aktivieren",
                    ["record.keymap.on.tip"] = "Hauptschalter. Ausgeschaltet werden Tasten unverändert aufgezeichnet und wiedergegeben und die Tabelle unten hat keine Wirkung.",
                    ["record.keymap.off"] = "Die Umbelegung ist aus; Tasten werden unverändert verwendet.",
                    ["record.keymap.off.tip"] = "Erklärt den aktuellen Zustand: die Tabelle wird ignoriert.",
                    ["record.keymap.note"] = "Links der Code, den die Taste tatsächlich sendet, rechts die Taste, die das Spiel sehen soll. Klicke auf ein Feld und drücke eine beliebige Taste zum Belegen; Esc bricht ab.",
                    ["record.keymap.note.tip"] = "Erklärt die Verwendung dieser Tabelle.",
                    ["record.keymap.empty"] = "Noch keine Einträge. Nutze die Schaltfläche unten, um einen hinzuzufügen.",
                    ["record.keymap.empty.tip"] = "Erklärt, dass die Tabelle leer ist.",
                    ["record.keymap.add"] = "Eintrag hinzufügen",
                    ["record.keymap.add.tip"] = "Fügt eine leere Zeile hinzu; belege danach beide Seiten durch Anklicken.",
                    ["ui.keymap.none"] = "Nicht belegt",
                    ["ui.keymap.none.tip"] = "Diesem Feld ist noch keine Taste zugewiesen.",
                    ["ui.keymap.clear"] = "Leeren",
                    ["ui.keymap.clear.tip"] = "Das Leeren der Zieltaste sorgt dafür, dass diese Taste gar keine Eingabe mehr erzeugt (eine einfache Möglichkeit, eine Taste zu sperren). Der linke Eintrag bleibt in der Tabelle.",
                    ["ui.keymap.delete"] = "Löschen",
