                    ["render.surface.clean_note"] = "Bez żadnego UI, dowolna rozdzielczość wyjściowa (dozwolony supersampling); dobre na czysty materiał albo do dalszego montażu.",
                    ["render.clock.experimental"] = "Deterministyczny zegar renderowania (eksperymentalny)",
                    ["render.clock.hint"] = "Zastępuje źródło czasu czytane przez grę zegarem wirtualnym sterowanym numerem klatki, czyniąc deterministycznym przesuwanie taktów, zdarzenia kamery, odliczania i planowanie dźwięków klawiatury — liczba klatek wyjściowych jest stała niezależnie od obciążenia maszyny. Wyłączone = awaryjnie kursor audio: renderowanie nadal działa, ale osią czasu jest kursor audio (jitter rzędu milisekund), a tła wideo nie są już dopasowane prędkością do tempa renderowania. Uwaga: to zmienia samo źródło czasu gry, więc zasięg skutków jest szerszy niż innych opcji; gdy jednocześnie działa inny mod renderujący wideo, oba walczą o ten sam punkt patcha (wygrywa pierwszy załadowany) i ta opcja ustępuje automatycznie. Jeśli renderowanie daje błędy lub pojawia się rozjazd dźwięku i obrazu, najpierw to wyłącz.",
