                    ["effects.decorations.tip"] = "Usuwa dekoracje, teksty i własne obiekty z mapy.",
                    ["effects.removealldecor.tip"] = "Czyści każdą dekorację. Po wyłączeniu dekoracje przywoływane przez zdarzenia warunkowe są zachowywane.",
                    ["effects.trackanim.tip"] = "Usuwa animacje pojawiania się/znikania torów, więc tory pokazują się od razu.",
                    ["effects.trackpos.tip"] = "Usuwa zdarzenia pozycji torów.",
                    ["effects.trackmove.tip"] = "Usuwa zdarzenia ruchu torów, najczęstszy rodzaj ruchu torów.",
                    ["effects.trackcolor.tip"] = "Usuwa zdarzenia koloru torów, więc tory zachowują jeden kolor.",
                    ["effects.resettrackopacity.tip"] = "Przywraca krycie pozostałych zdarzeń ruchu torów z powrotem do 100%.",
                    ["effects.resettrackanim.tip"] = "Zmienia animacje pojawiania się/znikania torów na przenikanie, aby tory nie znikały po usunięciu ich animacji.",
                    ["effects.resettrackcolor.tip"] = "Przywraca domyślny styl i kolor toru — pomarańczowy tor standardowy.",
                    ["effects.toggleall.tip"] = "Jeśli którykolwiek przełącznik w tej grupie jest włączony, jedno kliknięcie wyłącza wszystkie; jeśli wszystkie są wyłączone, jedno kliknięcie włącza wszystkie. Dotyczy tylko przełączników usuwających dany typ zdarzeń; resetów i opcji towarzyszących nie obejmuje.",
                    ["effects.planetorbit.tip"] = "Usuwa zdarzenia obrotu planety.",
                    ["effects.planetscale.tip"] = "Usuwa zdarzenia skali planety.",
                    ["effects.planetradius.tip"] = "Usuwa zdarzenia promienia planety.",
                    ["effects.hideicons.tip"] = "Usuwa zdarzenia ukrywania ikon.",
                    ["effects.hitsounds.tip"] = "Usuwa dźwięki trafień i zdarzenia własnych dźwięków. Utwór staje się cichy.",
                    ["effects.holdsounds.tip"] = "Usuwa zdarzenia dźwięków przytrzymania.",
                    ["effects.checkpoints.tip"] = "Usuwa punkty kontrolne, więc porażka w środku poziomu cofa cię na start.",
                    ["effects.inputevents.tip"] = "Usuwa zdarzenia wejścia, takie jak autoodtwarzanie i limity klawiszy.",
                    ["effects.framerate.tip"] = "Usuwa zdarzenia zmiany liczby klatek, więc cały poziom działa w jednym tempie.",
                    ["effects.repeatevents.tip"] = "Usuwa zdarzenia powtórzenia. Sekcje, których mapa używa przez nie wielokrotnie, zostają rozwinięte raz.",
                    ["record.recording.tip"] = "Główny przełącznik. Po wyłączeniu wejście do poziomu niczego nie nagrywa.",
                    ["record.autosave.tip"] = "Zapisuje tę próbę jako plik powtórki po ukończeniu poziomu.",
                    ["record.completesave.tip"] = "Zapisuj tylko pełne ukończenia. Wyłącz to, aby zachować też próby porzucone w połowie.",
                    ["record.dontsavewhenauto.tip"] = "Pomija poziomy, które gra odegrała sama, więc autoodtwarzanie nie zaleje listy powtórek.",
                    ["record.dontsavewhenmiss.tip"] = "Pomija próby zawierające pomyłkę. Wyłącz to, aby zachować nieudaną próbę.",
                    ["record.latesave.tip"] = "Zapisuj przy wychodzeniu z poziomu, a nie na ekranie wyników.",
                    ["record.failsave.tip"] = "Zapisuj też przy śmierci. Domyślnie plik powstaje tylko po ukończeniu lub przy ręcznym zapisie.",
                    ["record.backup.tip"] = "Przy zapisie zachowaj dodatkową kopię, aby istniejący plik nie został po prostu nadpisany.",
                    ["record.manualsave.tip"] = "Włącz F9 do ręcznego zapisu bieżącej próby, także próby w trakcie ćwiczenia.",
                    ["record.cancelsave.tip"] = "Odrzuca skrótem oczekujący zapis bieżącej próby. Po wyłączeniu skrót poniżej nic nie robi.",
                    ["record.asyncinput.tip"] = "Czytaj klawisze z asynchronicznego wejścia gry dla dokładniejszych znaczników czasu. Najpierw trzeba włączyć tę opcję w ustawieniach gry, inaczej nic się nie stanie.",
                    ["record.keybd.record.tip"] = "Nagraj stuknięcie jako osobną ścieżkę, aby odtwarzanie miało dźwięki klawiszy.",
                    ["record.keybd.volume.tip"] = "Głośność dźwięku klawiatury podczas odtwarzania. 0 = wyciszone.",
                    ["record.keybd.offset.tip"] = "Kalibruje dźwięk klawiatury całościowo: ujemne, jeśli jest za wczesny, dodatnie, jeśli za późny, w milisekundach.",
                    ["record.savekey.tip"] = "Skrót do zapisania tej próby, domyślnie F9. Kliknij go, a potem naciśnij dowolny klawisz, aby przypisać na nowo.",
                    ["record.cancelsavekey.tip"] = "Skrót, który odrzuca oczekujący zapis tej próby.",
                    ["render.on.tip"] = "Główny przełącznik renderowania wideo. Po wyłączeniu nie można rozpocząć nowego renderowania.",
                    ["render.width.tip"] = "Szerokość wyjściowa. Używana tylko przez czystą kamerę; ekran gry zależy od rozmiaru okna.",
                    ["render.height.tip"] = "Wysokość wyjściowa. Używana tylko przez czystą kamerę.",
                    ["render.fps.tip"] = "Liczba klatek wyjściowych. Wyższa = płynniej, a czas renderowania rośnie proporcjonalnie.",
                    ["render.tail.tip"] = "Dodatkowe sekundy nagrywane po zakończeniu poziomu, aby zachować animację wyjściową.",
                    ["render.surface.tip"] = "Źródło klatek. Czysta kamera nie ma UI i ma dowolną rozdzielczość; ekran gry zawiera UI i zależy od okna.",
                    ["render.cursor.tip"] = "Rysuje kursor myszy w wideo. Nowo nagrane replaye zapisują także trajektorię kursora, odtwarzaną wzdłuż osi czasu utworu — zsynchronizowaną z obrazem i niezależną od szybkości renderowania. Starsze replaye nie mają trajektorii i używają żywego kursora z czasu renderowania (jego tempo zależy od szybkości renderowania). Ukryty kursor nie jest rysowany.",
                    ["render.codec.tip"] = "Wybór kodera. Najszybciej preferuje kodowanie GPU i wraca do CPU, gdy wykrywanie się nie powiedzie; wiersz poniżej pokazuje, który jest faktycznie używany.",
                    ["render.quality.tip"] = "Jakość kodowania. Wyższa daje większe pliki i nieco dłuższe renderowanie.",
                    ["render.format.tip"] = "Kontener pliku wyjściowego. mp4 jest najbardziej kompatybilny; webm jest mniejszy, ale wymaga ponownego kodowania.",
                    ["render.outdir.tip"] = "Gdzie trafiają gotowe filmy. Puste = RenderVideos w folderze moda.",
                    ["render.clock.experimental.tip"] = "Zastępuje źródło czasu gry zegarem wirtualnym sterowanym numerem klatki, aby liczba klatek wyjściowych była stała niezależnie od obciążenia maszyny. Zmienia samo źródło czasu gry, więc zasięg skutków jest szeroki; najpierw to wyłącz, jeśli renderowanie daje błędy lub dźwięk się rozjeżdża.",
                    ["convert.target.tip"] = "Konwertuje istniejące filmy w folderze wyjściowym do tego formatu, niezależnie od formatu renderowania powyżej.",
