                    ["render.clock.hint"] = "Înlocuiește sursa de timp citită de joc cu un ceas virtual condus de indexul cadrului, făcând deterministe avansarea tacturilor, evenimentele camerei, numărătorile inverse și programarea sunetelor de tastatură — frecvența cadrelor de ieșire rămâne constantă indiferent de încărcarea mașinii. Oprit = cursor audio de rezervă: randarea funcționează în continuare, dar cronologia este condusă de cursorul audio (variații de milisecunde) și fundalurile video nu mai sunt sincronizate ca viteză cu rata de randare. Notă: modifică însăși sursa de timp a jocului, deci impactul este mai larg decât la alte opțiuni; când alt mod de randare video este activat simultan, ambele concurează pentru același punct de patch (câștigă primul încărcat) și această opțiune cedează automat. Dacă randarea dă erori sau apar decalaje audio/video, oprește mai întâi această opțiune.",
