                    ["render.cursor.tip"] = "Desenează cursorul mouse-ului în videoclip. Replay-urile înregistrate recent salvează și traiectoria cursorului, reprodusă de-a lungul liniei de timp a piesei — sincronizată cu imaginea și independentă de viteza de randare. Replay-urile mai vechi nu au traiectorie și revin la cursorul live din momentul randării (ritmul urmează viteza de randare). Un cursor ascuns nu este desenat.",
