                    ["render.clock.hint"] = "Заменяет источник времени, который читает игра, на виртуальные часы, управляемые номером кадра: продвижение долей, события камеры, обратные отсчёты и планирование звуков клавиш становятся детерминированными — частота кадров на выходе постоянна независимо от нагрузки на машину. Выкл. = запасной вариант по аудиокурсору: рендер работает, но шкалой времени управляет аудиокурсор (дрожание в миллисекундах), а фоновые видео больше не согласованы по скорости с темпом рендера. Внимание: это меняет сам источник времени игры, поэтому последствия шире, чем у других опций; если одновременно включён другой мод видеорендера, оба конкурируют за одну точку патча (побеждает загрузившийся первым), и эта опция автоматически уступает. Если рендер выдаёт ошибки или звук расходится с видео, сначала выключите её.",
