                    ["render.clock.hint"] = "Thay nguồn thời gian mà game đọc bằng đồng hồ ảo điều khiển bởi số khung hình, khiến việc tiến nhịp, sự kiện camera, đếm ngược và lên lịch âm phím đều tất định — tốc độ khung hình đầu ra không đổi bất kể máy bận. Tắt = dự phòng theo con trỏ âm thanh: kết xuất vẫn chạy, nhưng trục thời gian do con trỏ âm thanh điều khiển (rung ở mức mili giây) và nền video không còn khớp tốc độ với tốc độ kết xuất. Lưu ý: tùy chọn này đổi chính nguồn thời gian của game nên phạm vi ảnh hưởng rộng hơn các tùy chọn khác; khi một mod kết xuất video khác cùng bật, cả hai tranh cùng một điểm vá (bên tải trước thắng) và tùy chọn này tự nhường. Nếu kết xuất báo lỗi hoặc âm thanh lệch hình, hãy tắt mục này trước.",
